cat << 'EOF' > /workspace/generate_summary.js
const XLSX = require("xlsx");
const docx = require("docx");
const fs = require("fs");

const { Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
        WidthType, AlignmentType, BorderStyle, HeadingLevel } = docx;

// Read spreadsheet
const wb = XLSX.readFile("/workspace/testbed/data/product_inventory.xlsx");
const rows = XLSX.utils.sheet_to_json(wb.Sheets["Products"]);

// Compute stats
const totalProducts = rows.length;
const categories = {};
rows.forEach(r => {
  const cat = (r["Category"] || "").toLowerCase();
  categories[cat] = (categories[cat] || 0) + 1;
});
const prices = rows.map(r => r["Price"] || 0);
const minPrice = Math.min(...prices);
const maxPrice = Math.max(...prices);
const avgPrice = (prices.reduce((a, b) => a + b, 0) / prices.length).toFixed(2);
const allInStock = rows.every(r => String(r["In Stock"]).toLowerCase() === "yes");

// Helper: bordered cell
const noBorder = { style: BorderStyle.SINGLE, size: 1, color: "CCCCCC" };
const borders = { top: noBorder, bottom: noBorder, left: noBorder, right: noBorder };

function cell(text, opts = {}) {
  return new TableCell({
    borders,
    width: opts.width ? { size: opts.width, type: WidthType.PERCENTAGE } : undefined,
    children: [new Paragraph({
      spacing: { before: 40, after: 40 },
      children: [new TextRun({ text: String(text), bold: !!opts.bold, size: 22, font: "Calibri" })]
    })]
  });
}

// Build product table rows
const headerRow = new TableRow({
  children: ["Product ID", "Name", "Category", "Price"].map(h => cell(h, { bold: true }))
});
const dataRows = rows.map(r => new TableRow({
  children: [
    cell(r["Product ID"]),
    cell(r["Name"]),
    cell(r["Category"]),
    cell(`$${r["Price"]}`)
  ]
}));

// Category breakdown lines
const catLines = Object.entries(categories)
  .sort((a, b) => b[1] - a[1])
  .map(([cat, count]) => `${cat.charAt(0).toUpperCase() + cat.slice(1)}: ${count}`);

// Build document
const doc = new Document({
  sections: [{
    properties: {},
    children: [
      new Paragraph({
        heading: HeadingLevel.HEADING_1,
        spacing: { after: 200 },
        children: [new TextRun({ text: "Product Inventory Summary", bold: true, size: 32, font: "Calibri" })]
      }),
      new Paragraph({
        spacing: { after: 200 },
        children: [new TextRun({ text: `This report provides a summary of the current product inventory sourced from product_inventory.xlsx.`, size: 22, font: "Calibri" })]
      }),

      // Overview
      new Paragraph({
        heading: HeadingLevel.HEADING_2,
        spacing: { before: 200, after: 100 },
        children: [new TextRun({ text: "Overview", bold: true, size: 26, font: "Calibri" })]
      }),
      ...[
        `Total Products: ${totalProducts}`,
        `Price Range: $${minPrice} – $${maxPrice}`,
        `Average Price: $${avgPrice}`,
        `Stock Status: All ${totalProducts} listed items are marked In Stock as Yes.`
      ].map(t => new Paragraph({
        spacing: { before: 40, after: 40 },
        bullet: { level: 0 },
        children: [new TextRun({ text: t, size: 22, font: "Calibri" })]
      })),

      // Category breakdown
      new Paragraph({
        heading: HeadingLevel.HEADING_2,
        spacing: { before: 200, after: 100 },
        children: [new TextRun({ text: "Category Breakdown", bold: true, size: 26, font: "Calibri" })]
      }),
      ...catLines.map(t => new Paragraph({
        spacing: { before: 40, after: 40 },
        bullet: { level: 0 },
        children: [new TextRun({ text: t, size: 22, font: "Calibri" })]
      })),

      // Product listing
      new Paragraph({
        heading: HeadingLevel.HEADING_2,
        spacing: { before: 200, after: 100 },
        children: [new TextRun({ text: "Product Listing", bold: true, size: 26, font: "Calibri" })]
      }),
      new Paragraph({
        spacing: { after: 100 },
        children: [new TextRun({ text: "The In Stock column has been omitted from the table below as all items are confirmed in stock.", size: 22, font: "Calibri", italics: true })]
      }),
      new Table({
        width: { size: 100, type: WidthType.PERCENTAGE },
        rows: [headerRow, ...dataRows]
      }),
    ]
  }]
});

Packer.toBuffer(doc).then(buf => {
  const outPath = "/workspace/data/product_inventory_summary.docx";
  fs.writeFileSync(outPath, buf);
  console.log("Document saved to " + outPath);
});
